INSERT INTO `services_i18n` (`id`, `service_id`, `locale`, `slug`, `name`, `summary`, `content`, `image_alt`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
('10000001-0000-4000-8000-0001861468', '10000000-0000-4000-8000-0001861468', 'tr', 'lead-bulma-rakip-takip-paneli', 'firmanıza özel lead bulma ve rakip takip paneli kurarım', 'Merhaba! Firmanıza özel, müşteri ve rakiplerinizi tek panelden takip edebileceğiniz bir B2B lead bulma ve pazar takip yazılımı geliştiriyorum. Sektörünüze (otomotiv yan sanayi, plastik enjeksiyon, makina, ihracat vb.) göre uyarlıyorum. ✅ NELER YAPIYORUM • Lead Machine — Amazon satıcı, B2B dizin (Europages/Kompass/Google Maps) ve fuar katılımcı taraması ile otomatik potansiyel müşteri üretimi • ICP (ideal müşteri profili) eşleştirme ve 0–100 puanlama • Lead pipeline — kanban panel (Yeni → Görüşme', '{"source":"bionluk","source_id":861468,"category":"İş & Yönetim > Satış & Müşteri Bulma","packages":[{"title":"TEMEL — 20.000 ₺","price":20000,"currency":"TRY","duration_days":10,"revisions":1,"description":"Tek sektör için lead bulma + takip paneli. Seçtiğiniz 1 kanaldan (Amazon, B2B dizin veya fuar) ICP eşleşm","options":[{"title":"Lead(müşteri adayı) sayısı","value":100,"unit":" lead"},{"title":"Çalışma Saati","value":40,"unit":" saat"},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":false,"unit":null}]},{"title":"STANDART — 30.000 ₺","price":30000,"currency":"TRY","duration_days":20,"revisions":2,"description":"TEMEL''in tümü + 2 kaynaktan 300 aday, churn risk skoru, pazar sinyalleri (rakip site/fiyat takibi), karar","options":[{"title":"Lead(müşteri adayı) sayısı","value":200,"unit":null},{"title":"Çalışma Saati","value":50,"unit":null},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":true,"unit":null}]},{"title":"PRO — 50.000 ₺","price":50000,"currency":"TRY","duration_days":30,"revisions":5,"description":"STANDART''ın tümü + 3 kaynaktan 1000 aday, otomatik scraper sinyalleri, AI outreach e-posta taslağı, ERP/C","options":[{"title":"Lead(müşteri adayı) sayısı","value":1000,"unit":null},{"title":"Çalışma Saati","value":50,"unit":null},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":true,"unit":null}]}],"html":"Merhaba! Firmanıza özel, müşteri ve rakiplerinizi tek panelden takip edebileceğiniz bir B2B lead bulma ve pazar takip yazılımı geliştiriyorum. Sektörünüze (otomotiv yan sanayi, plastik enjeksiyon, makina, ihracat vb.) göre uyarlıyorum.\\n\\n✅ NELER YAPIYORUM\\n\\n• Lead Machine — Amazon satıcı, B2B dizin (Europages/Kompass/Google Maps) ve fuar katılımcı taraması ile otomatik potansiyel müşteri üretimi\\n• ICP (ideal müşteri profili) eşleştirme ve 0–100 puanlama\\n• Lead pipeline — kanban panel (Yeni → Görüşmede → Teklif → Dönüştürüldü)\\n• Churn (kayıp) risk skoru — sinyal, aktivite ve sipariş verisinden otomatik hesap\\n• Pazar sinyalleri — rakip site/fiyat değişikliği, sosyal aktivite takibi (scraper ile otomatik)\\n• Karar verici e-posta bulma (enrichment) + AI destekli outreach e-posta taslağı\\n• Haftalık PDF raporu + e-posta bildirimi\\n• Mevcut ERP/CRM''inizle entegrasyon\\n\\n🛠️ TEKNOLOJİLER\\nNext.js 16, React 19, TypeScript, Tailwind, Fastify, MySQL, Python scraper, Docker. Her müşteri için ayrı, bağımsız kurulum (kendi verileriniz size özel).\\n\\n🚀 NASIL ÇALIŞIYORUZ\\n1) İhtiyaç görüşmesi ve hedef sektör/ICP belirleme\\n2) Demo panel ve kapsam onayı\\n3) Geliştirme + scraper kaynaklarının kurulumu\\n4) Test, eğitim ve canlıya alma\\n\\nPortföyümdeki MarketPulse, bu sistemin uçtan uca geliştirdiğim canlı bir örneğidir. Kapsam ve bütçe için lütfen mesaj atın — projenize özel net bir teklif çıkarayım.","llms_summary":"GZL Teknoloji tarafından firmanıza özel lead bulma ve rakip takip paneli kurarım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["İş & Yönetim","Satış & Müşteri Bulma"]}', 'firmanıza özel lead bulma ve rakip takip paneli kurarım', 'firmanıza özel lead bulma ve rakip takip paneli kurarım | GZL Teknoloji', 'Merhaba! Firmanıza özel, müşteri ve rakiplerinizi tek panelden takip edebileceğiniz bir B2B lead bulma ve pazar takip yazılımı geliştiriyorum. Sektörünüze (otomotiv yan sanayi, plastik enjeksiyon, makina, ihracat vb.) göre uyarlıyorum. ✅ NELER YAPIYORUM • Lead Machine — Amazon satıcı, B2B dizin (Europages/Kompass/Google Maps) ve fuar katılımcı taraması ile otomatik potansiyel müşteri üretimi • ICP (ideal müşteri profili) eşleştirme ve 0–100 puanlama • Lead pipeline — kanban panel (Yeni → Görüşme', 'İş & Yönetim,Satış & Müşteri Bulma,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0001861468', '10000000-0000-4000-8000-0001861468', 'en', 'lead-generation-competitor-monitoring-dashboard', 'Custom B2B Lead Generation & Competitor Monitoring Dashboard', 'We build a custom B2B lead generation and market monitoring platform that lets you track prospects and competitors from a single dashboard. The system is tailored to your industry — automotive suppliers, plastic injection, machinery, export businesses and more. WHAT WE DELIVER - Lead Machine — automated prospect generation from Amazon seller scans, B2B directories (Europages/Kompass/Google Maps) and trade fair exhibitor lists - ICP (ideal customer profile) matching with 0–100 scoring - Lead pipe', '{"source":"bionluk","source_id":861468,"category":"İş & Yönetim > Satış & Müşteri Bulma","packages":[{"title":"BASIC — 20,000 ₺","price":20000,"currency":"TRY","duration_days":10,"revisions":1,"description":"Lead generation + tracking dashboard for a single industry. ICP matching from one channel of your choice (Amazon, B2B directory or trade fairs).","options":[{"title":"Lead(müşteri adayı) sayısı","value":100,"unit":" lead"},{"title":"Çalışma Saati","value":40,"unit":" saat"},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":false,"unit":null}]},{"title":"STANDARD — 30,000 ₺","price":30000,"currency":"TRY","duration_days":20,"revisions":2,"description":"Everything in BASIC + 300 prospects from 2 sources, churn risk scoring, market signals (competitor site/price tracking) and decision-maker email discovery.","options":[{"title":"Lead(müşteri adayı) sayısı","value":200,"unit":null},{"title":"Çalışma Saati","value":50,"unit":null},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":true,"unit":null}]},{"title":"PRO — 50,000 ₺","price":50000,"currency":"TRY","duration_days":30,"revisions":5,"description":"Everything in STANDARD + 1,000 prospects from 3 sources, automated scraper signals, AI outreach email drafts and ERP/CRM integration.","options":[{"title":"Lead(müşteri adayı) sayısı","value":1000,"unit":null},{"title":"Çalışma Saati","value":50,"unit":null},{"title":"Biçimlendirme ve Temizleme","value":true,"unit":null},{"title":"Lead Kontrolü","value":true,"unit":null}]}],"html":"We build a custom B2B lead generation and market monitoring platform that lets you track prospects and competitors from a single dashboard. The system is tailored to your industry — automotive suppliers, plastic injection, machinery, export businesses and more.\\n\\nWHAT WE DELIVER\\n\\n- Lead Machine — automated prospect generation from Amazon seller scans, B2B directories (Europages/Kompass/Google Maps) and trade fair exhibitor lists\\n- ICP (ideal customer profile) matching with 0–100 scoring\\n- Lead pipeline — kanban board (New → In Contact → Quoted → Converted)\\n- Churn risk score — calculated automatically from signals, activity and order data\\n- Market signals — competitor website/price changes and social activity tracking (automated via scrapers)\\n- Decision-maker email discovery (enrichment) plus AI-assisted outreach email drafts\\n- Weekly PDF report with email notifications\\n- Integration with your existing ERP/CRM\\n\\nTECHNOLOGY\\n\\nNext.js 16, React 19, TypeScript, Tailwind, Fastify, MySQL, Python scrapers, Docker. Each client gets a separate, standalone deployment — your data remains exclusively yours.\\n\\nHOW WE WORK\\n\\n1) Discovery call to define your target industry and ICP\\n2) Demo dashboard and scope approval\\n3) Development and scraper source setup\\n4) Testing, training and go-live\\n\\nMarketPulse in our portfolio is a live, end-to-end deployment of this system. Message us with your scope and budget and we will prepare a clear, project-specific proposal.","llms_summary":"Custom B2B Lead Generation & Competitor Monitoring Dashboard is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["İş & Yönetim","Satış & Müşteri Bulma"]}', 'Custom B2B Lead Generation & Competitor Monitoring Dashboard', 'Custom B2B Lead Generation & Competitor Monitoring Dashboard | GZL Technology', 'We build a custom B2B lead generation and market monitoring platform that lets you track prospects and competitors from a single dashboard. The system is tailored to your industry — automotive suppliers, plastic injection, machinery, export businesses and more. WHAT WE DELIVER - Lead Machine — automated prospect generation from Amazon seller scans, B2B directories (Europages/Kompass/Google Maps) and trade fair exhibitor lists - ICP (ideal customer profile) matching with 0–100 scoring - Lead pipe', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0002861494', '10000000-0000-4000-8000-0002861494', 'tr', 'sosyal-medya-otomasyon-paneli', 'markanıza özel sosyal medya otomasyon paneli kurarım', 'Merhaba. İşletmeniz için sosyal medya içeriklerinizi tek panelden planlayıp zamanlayabileceğiniz bir web yazılımı geliştiriyorum. Amaç; gönderilerinizi önceden hazırlamak, takvime almak ve performansını ölçmektir. Neler yapıyorum: - Instagram, Facebook, LinkedIn, X ve YouTube hesaplarınızı tek panelde toplama (platformların resmi API bağlantılarıyla) - İçerik takvimi ve gönderi zamanlama (sürükle bırak, en uygun saat önerisi) - Tek içeriği farklı platformlara uyarlama ve yayın öncesi önizleme - ', '{"source":"bionluk","source_id":861494,"category":"İnternet Reklamcılığı > Sosyal Medya Yönetimi","packages":[{"title":"TEMEL — 15.000 ₺","price":15000,"currency":"TRY","duration_days":7,"revisions":1,"description":"Tek marka için 2 platforma (örn. Instagram + Facebook) zamanlanmış yayın ve içerik takvimi paneli. ","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]},{"title":"STANDART — 25.000 ₺","price":25000,"currency":"TRY","duration_days":15,"revisions":3,"description":"TEMEL''in tümü + 4 platform, 3 marka/hesap, AI içerik asistanı (metin & hashtag), ","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]},{"title":"PRO — 45.000 ₺","price":45000,"currency":"TRY","duration_days":30,"revisions":5,"description":"STANDART''ın tümü + 6+ platform (Ads dahil), sınırsız marka/hesap, çoklu kullanıcı & rol yönetimi, GA4/Ads","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]}],"html":"Merhaba. İşletmeniz için sosyal medya içeriklerinizi tek panelden planlayıp zamanlayabileceğiniz bir web yazılımı geliştiriyorum. Amaç; gönderilerinizi önceden hazırlamak, takvime almak ve performansını ölçmektir.\\n\\nNeler yapıyorum:\\n- Instagram, Facebook, LinkedIn, X ve YouTube hesaplarınızı tek panelde toplama (platformların resmi API bağlantılarıyla)\\n- İçerik takvimi ve gönderi zamanlama (sürükle bırak, en uygun saat önerisi)\\n- Tek içeriği farklı platformlara uyarlama ve yayın öncesi önizleme\\n- Yapay zeka destekli metin ve etiket önerisi (isteğe bağlı)\\n- İçerik şablonları ve etiket grupları\\n- Temel performans raporu (gösterim, etkileşim, tıklama)\\n- Çok kullanıcılı ve çok markalı kullanım, rol yönetimi\\n\\nNasıl çalışıyoruz:\\n1) İhtiyaç ve hesap kapsamının belirlenmesi\\n2) Demo panel ve onay\\n3) Geliştirme ve resmi API bağlantıları\\n4) Test, kısa eğitim ve teslim\\n\\nYazılım tamamen size özel ve bağımsız kurulur; verileriniz sizde kalır. Kullandığım teknolojiler: Next.js, React, Fastify, MySQL. Kapsam ve fiyat için lütfen mesaj gönderin.","llms_summary":"GZL Teknoloji tarafından markanıza özel sosyal medya otomasyon paneli kurarım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["İnternet Reklamcılığı","Sosyal Medya Yönetimi"]}', 'markanıza özel sosyal medya otomasyon paneli kurarım', 'markanıza özel sosyal medya otomasyon paneli kurarım | GZL Teknoloji', 'Merhaba. İşletmeniz için sosyal medya içeriklerinizi tek panelden planlayıp zamanlayabileceğiniz bir web yazılımı geliştiriyorum. Amaç; gönderilerinizi önceden hazırlamak, takvime almak ve performansını ölçmektir. Neler yapıyorum: - Instagram, Facebook, LinkedIn, X ve YouTube hesaplarınızı tek panelde toplama (platformların resmi API bağlantılarıyla) - İçerik takvimi ve gönderi zamanlama (sürükle bırak, en uygun saat önerisi) - Tek içeriği farklı platformlara uyarlama ve yayın öncesi önizleme - ', 'İnternet Reklamcılığı,Sosyal Medya Yönetimi,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0002861494', '10000000-0000-4000-8000-0002861494', 'en', 'social-media-automation-dashboard', 'Custom Social Media Automation Dashboard for Your Brand', 'We develop a custom web platform that lets your business plan, schedule and publish social media content from a single dashboard. Prepare posts in advance, place them on a calendar and measure their performance. WHAT WE DELIVER - Instagram, Facebook, LinkedIn, X and YouTube accounts managed from one dashboard (via the platforms'' official APIs) - Content calendar and post scheduling (drag and drop, best-time suggestions) - Adapting a single piece of content to different platforms, with pre-publis', '{"source":"bionluk","source_id":861494,"category":"İnternet Reklamcılığı > Sosyal Medya Yönetimi","packages":[{"title":"BASIC — 15,000 ₺","price":15000,"currency":"TRY","duration_days":7,"revisions":1,"description":"Scheduled publishing and content calendar dashboard for a single brand on 2 platforms (e.g. Instagram + Facebook).","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]},{"title":"STANDARD — 25,000 ₺","price":25000,"currency":"TRY","duration_days":15,"revisions":3,"description":"Everything in BASIC + 4 platforms, 3 brands/accounts and an AI content assistant (copy & hashtags).","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]},{"title":"PRO — 45,000 ₺","price":45000,"currency":"TRY","duration_days":30,"revisions":5,"description":"Everything in STANDARD + 6+ platforms (Ads included), unlimited brands/accounts, multi-user & role management and GA4/Ads reporting.","options":[{"title":"Sayfa/Kanal Değerlendirmesi","value":true,"unit":null}]}],"html":"We develop a custom web platform that lets your business plan, schedule and publish social media content from a single dashboard. Prepare posts in advance, place them on a calendar and measure their performance.\\n\\nWHAT WE DELIVER\\n\\n- Instagram, Facebook, LinkedIn, X and YouTube accounts managed from one dashboard (via the platforms'' official APIs)\\n- Content calendar and post scheduling (drag and drop, best-time suggestions)\\n- Adapting a single piece of content to different platforms, with pre-publish preview\\n- AI-assisted copy and hashtag suggestions (optional)\\n- Content templates and hashtag groups\\n- Core performance reporting (impressions, engagement, clicks)\\n- Multi-user and multi-brand usage with role management\\n\\nHOW WE WORK\\n\\n1) Defining requirements and account scope\\n2) Demo dashboard and approval\\n3) Development and official API connections\\n4) Testing, a short training session and handover\\n\\nThe software is deployed as a fully independent installation dedicated to you; your data stays with you. Technology stack: Next.js, React, Fastify, MySQL. Message us for scope and pricing.","llms_summary":"Custom Social Media Automation Dashboard for Your Brand is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["İnternet Reklamcılığı","Sosyal Medya Yönetimi"]}', 'Custom Social Media Automation Dashboard for Your Brand', 'Custom Social Media Automation Dashboard for Your Brand | GZL Technology', 'We develop a custom web platform that lets your business plan, schedule and publish social media content from a single dashboard. Prepare posts in advance, place them on a calendar and measure their performance. WHAT WE DELIVER - Instagram, Facebook, LinkedIn, X and YouTube accounts managed from one dashboard (via the platforms'' official APIs) - Content calendar and post scheduling (drag and drop, best-time suggestions) - Adapting a single piece of content to different platforms, with pre-publis', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0003850998', '10000000-0000-4000-8000-0003850998', 'tr', 'geo-seo-lighthouse-analizi', ' web siteniz için GEO + SEO + Lighthouse analizi yaparım', 'Web sitenizin Google''da değil, ChatGPT, Gemini ve Perplexity''de de görünmesini sağlıyorum. GEO (Generative Engine Optimization) nedir? Kullanıcılar artık bilgiye yapay zeka asistanlarından ulaşıyor. GEO, sitenizin bu sistemlerde nasıl algılandığını, alıntılanıp alıntılanmadığını ölçer ve iyileştirir. Analiz kapsamı: ► GEO & AI Görünürlük - AI alıntılanabilirlik skoru (0-100) - ChatGPT, Gemini, Perplexity, Google AI Overviews hazırlık durumu - AI crawler erişim kontrolü (GPTBot, ClaudeBot, Perple', '{"source":"bionluk","source_id":850998,"category":"Yazılım & Teknoloji > Diğer Yazılım Teknoloji","packages":[{"title":"Temel analiz","price":100,"currency":"TRY","duration_days":1,"revisions":0,"description":"Analiz hizmeti bulgular + aksiyon planı içerir. ","options":[]},{"title":"","price":0,"currency":"TRY","duration_days":0,"revisions":0,"description":"","options":[]},{"title":"","price":0,"currency":"TRY","duration_days":0,"revisions":0,"description":"","options":[]}],"html":"Web sitenizin Google''da değil, ChatGPT, Gemini ve Perplexity''de de görünmesini sağlıyorum.\\n\\nGEO (Generative Engine Optimization) nedir?\\nKullanıcılar artık bilgiye yapay zeka asistanlarından ulaşıyor. GEO, sitenizin bu sistemlerde nasıl algılandığını, alıntılanıp alıntılanmadığını ölçer ve iyileştirir.\\n\\nAnaliz kapsamı:\\n\\n► GEO & AI Görünürlük\\n- AI alıntılanabilirlik skoru (0-100)\\n- ChatGPT, Gemini, Perplexity, Google AI Overviews hazırlık durumu\\n- AI crawler erişim kontrolü (GPTBot, ClaudeBot, PerplexityBot vb.)\\n- llms.txt standart uyumluluğu\\n- Schema.org / JSON-LD yapılandırılmış veri denetimi\\n- Marka bilinirliği ve AI sistemlerinde referans görünürlüğü\\n\\n► Teknik SEO\\n- robots.txt, sitemap.xml, canonical URL kontrolü\\n- Meta etiketleri, Open Graph, Twitter Card\\n- İç bağlantı yapısı ve anchor text analizi\\n- Index/noindex durumu\\n\\n► Lighthouse & Core Web Vitals\\n- Performans skoru (LCP, INP, CLS metrikleri)\\n- Mobil uyumluluk ve erişilebilirlik\\n- Kaynak optimizasyonu (JS, CSS, görseller)\\n\\nTeslim edilen rapor:\\nProfesyonel PDF; skor göstergeleri, platform bazlı hazırlık tablosu, öncelikli aksiyon planı ve geliştiricinize iletebileceğiniz teknik notlar içerir.\\n\\nDaha önce analiz ettiğim siteler: energetische-massage-bonn.de, paketjet.com, sportoonline.com, guezelwebdesign.com ve daha fazlası.\\n\\nSadece URL yeterli — siteye erişim gerekmez.","llms_summary":"GZL Teknoloji tarafından web siteniz için GEO + SEO + Lighthouse analizi yaparım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["Yazılım & Teknoloji","Diğer Yazılım Teknoloji"]}', ' web siteniz için GEO + SEO + Lighthouse analizi yaparım', ' web siteniz için GEO + SEO + Lighthouse analizi yaparım | GZL Teknoloji', 'Web sitenizin Google''da değil, ChatGPT, Gemini ve Perplexity''de de görünmesini sağlıyorum. GEO (Generative Engine Optimization) nedir? Kullanıcılar artık bilgiye yapay zeka asistanlarından ulaşıyor. GEO, sitenizin bu sistemlerde nasıl algılandığını, alıntılanıp alıntılanmadığını ölçer ve iyileştirir. Analiz kapsamı: ► GEO & AI Görünürlük - AI alıntılanabilirlik skoru (0-100) - ChatGPT, Gemini, Perplexity, Google AI Overviews hazırlık durumu - AI crawler erişim kontrolü (GPTBot, ClaudeBot, Perple', 'Yazılım & Teknoloji,Diğer Yazılım Teknoloji,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0003850998', '10000000-0000-4000-8000-0003850998', 'en', 'geo-seo-lighthouse-audit', 'GEO + SEO + Lighthouse Audit for Your Website', 'We make your website visible not only on Google, but also in ChatGPT, Gemini and Perplexity. What is GEO (Generative Engine Optimization)? Users increasingly reach information through AI assistants. GEO measures and improves how your site is perceived by these systems — and whether it gets cited. AUDIT SCOPE GEO & AI Visibility - AI citability score (0–100) - Readiness status for ChatGPT, Gemini, Perplexity and Google AI Overviews - AI crawler access review (GPTBot, ClaudeBot, PerplexityBot, etc', '{"source":"bionluk","source_id":850998,"category":"Yazılım & Teknoloji > Diğer Yazılım Teknoloji","packages":[{"title":"Essential Audit","price":100,"currency":"TRY","duration_days":1,"revisions":0,"description":"The audit includes findings plus an action plan.","options":[]},{"title":"","price":0,"currency":"TRY","duration_days":0,"revisions":0,"description":"","options":[]},{"title":"","price":0,"currency":"TRY","duration_days":0,"revisions":0,"description":"","options":[]}],"html":"We make your website visible not only on Google, but also in ChatGPT, Gemini and Perplexity.\\n\\nWhat is GEO (Generative Engine Optimization)?\\nUsers increasingly reach information through AI assistants. GEO measures and improves how your site is perceived by these systems — and whether it gets cited.\\n\\nAUDIT SCOPE\\n\\nGEO & AI Visibility\\n- AI citability score (0–100)\\n- Readiness status for ChatGPT, Gemini, Perplexity and Google AI Overviews\\n- AI crawler access review (GPTBot, ClaudeBot, PerplexityBot, etc.)\\n- llms.txt standard compliance\\n- Schema.org / JSON-LD structured data audit\\n- Brand awareness and reference visibility across AI systems\\n\\nTechnical SEO\\n- robots.txt, sitemap.xml and canonical URL checks\\n- Meta tags, Open Graph, Twitter Card\\n- Internal link structure and anchor text analysis\\n- Index/noindex status\\n\\nLighthouse & Core Web Vitals\\n- Performance score (LCP, INP, CLS metrics)\\n- Mobile friendliness and accessibility\\n- Resource optimization (JS, CSS, images)\\n\\nDELIVERED REPORT\\nA professional PDF including score gauges, a platform-by-platform readiness table, a prioritized action plan and technical notes you can hand directly to your developer.\\n\\nSites we have previously audited include energetische-massage-bonn.de, paketjet.com, sportoonline.com, guezelwebdesign.com and more.\\n\\nA URL is all we need — no site access required.","llms_summary":"GEO + SEO + Lighthouse Audit for Your Website is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["Yazılım & Teknoloji","Diğer Yazılım Teknoloji"]}', 'GEO + SEO + Lighthouse Audit for Your Website', 'GEO + SEO + Lighthouse Audit for Your Website | GZL Technology', 'We make your website visible not only on Google, but also in ChatGPT, Gemini and Perplexity. What is GEO (Generative Engine Optimization)? Users increasingly reach information through AI assistants. GEO measures and improves how your site is perceived by these systems — and whether it gets cited. AUDIT SCOPE GEO & AI Visibility - AI citability score (0–100) - Readiness status for ChatGPT, Gemini, Perplexity and Google AI Overviews - AI crawler access review (GPTBot, ClaudeBot, PerplexityBot, etc', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0004861502', '10000000-0000-4000-8000-0004861502', 'tr', 'ai-ml-veri-tahmin-platformu', 'AI ve ML tabanlı veri tahmin platformu geliştiririm', 'Merhaba! Verinizi tahmine ve karara dönüştüren, AI/ML destekli bir analiz ve tahmin platformu geliştiriyorum. Ar-Ge ekipleri, tarım/biyoteknoloji ve veri yoğun işletmeler için uçtan uca kurulum. ✅ NELER YAPIYORUM • Makine öğrenmesi tahmin motoru (regresyon/sınıflandırma) — güven aralığı ile • Python ML servisi (FastAPI, scikit-learn; gerektiğinde R/sommer entegrasyonu) • Model versiyonlama ve deney takibi (MLflow) • Büyük veri işleme (Parquet/DuckDB), CSV/VCF içe aktarma ve veri kalite kontrolü ', '{"source":"bionluk","source_id":861502,"category":"Yazılım & Teknoloji > Data Analizi & Raporlama","packages":[{"title":"Tahmin Paneli","price":25000,"currency":"TRY","duration_days":7,"revisions":1,"description":"Tek veri seti için 1 ML tahmin modeli (regresyon/sınıflandırma) + güven aralığı, sonuç tablosu ve temel g","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]},{"title":"ML Analiz Sistemi","price":50000,"currency":"TRY","duration_days":15,"revisions":4,"description":"TEMEL''in tümü + 3 model, model versiyonlama (MLflow), gelişmiş görselleştirme (Manhattan/PCA/dağılım), CS","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]},{"title":"Tam AI Platform","price":100000,"currency":"TRY","duration_days":40,"revisions":8,"description":"STANDART''ın tümü + sınırsız model, otomatik yeniden eğitim döngüsü, AI/LLM yorum katmanı, sıralama/seçim ","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]}],"html":"Merhaba! Verinizi tahmine ve karara dönüştüren, AI/ML destekli bir analiz ve tahmin platformu geliştiriyorum. Ar-Ge ekipleri, tarım/biyoteknoloji ve veri yoğun işletmeler için uçtan uca kurulum.\\n\\n✅ NELER YAPIYORUM\\n\\n• Makine öğrenmesi tahmin motoru (regresyon/sınıflandırma) — güven aralığı ile\\n• Python ML servisi (FastAPI, scikit-learn; gerektiğinde R/sommer entegrasyonu)\\n• Model versiyonlama ve deney takibi (MLflow)\\n• Büyük veri işleme (Parquet/DuckDB), CSV/VCF içe aktarma ve veri kalite kontrolü\\n• Etkileşimli görselleştirme — dağılım, bar, Manhattan/GWAS, PCA grafikleri\\n• AI/LLM yorum katmanı (Groq/OpenAI) — sonuçları sade dille açıklar\\n• Yönetim paneli: tahmin, raporlama, sıralama/seçim indeksi\\n• Otomatik yeniden eğitim döngüsü ve denetim izi\\n\\n🛠️ TEKNOLOJİLER\\nFastify, Bun, TypeScript, Drizzle ORM, MySQL · Python, FastAPI, scikit-learn, MLflow · Next.js 16, Tailwind, Shadcn UI · Docker. Size özel, bağımsız kurulum.\\n\\n🚀 NASIL ÇALIŞIYORUZ\\n1) Veri ve hedef metrik belirleme\\n2) Demo model + kapsam onayı\\n3) Geliştirme, model eğitimi ve doğrulama\\n4) Panel teslimi, eğitim ve canlıya alma\\n\\nÖrnek referansım GenomAI — bitki ıslahı için genomik tahmin (GEBV) ve GWAS platformu. Projenize özel net teklif için lütfen mesaj atın.","llms_summary":"GZL Teknoloji tarafından AI ve ML tabanlı veri tahmin platformu geliştiririm hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["Yazılım & Teknoloji","Data Analizi & Raporlama"]}', 'AI ve ML tabanlı veri tahmin platformu geliştiririm', 'AI ve ML tabanlı veri tahmin platformu geliştiririm | GZL Teknoloji', 'Merhaba! Verinizi tahmine ve karara dönüştüren, AI/ML destekli bir analiz ve tahmin platformu geliştiriyorum. Ar-Ge ekipleri, tarım/biyoteknoloji ve veri yoğun işletmeler için uçtan uca kurulum. ✅ NELER YAPIYORUM • Makine öğrenmesi tahmin motoru (regresyon/sınıflandırma) — güven aralığı ile • Python ML servisi (FastAPI, scikit-learn; gerektiğinde R/sommer entegrasyonu) • Model versiyonlama ve deney takibi (MLflow) • Büyük veri işleme (Parquet/DuckDB), CSV/VCF içe aktarma ve veri kalite kontrolü ', 'Yazılım & Teknoloji,Data Analizi & Raporlama,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0004861502', '10000000-0000-4000-8000-0004861502', 'en', 'ai-ml-data-forecasting-platform', 'AI & ML Data Forecasting Platform Development', 'We build AI/ML-powered analytics and forecasting platforms that turn your data into predictions and decisions. End-to-end setup for R&D teams, agriculture/biotechnology organizations and data-intensive businesses. WHAT WE DELIVER - Machine learning prediction engine (regression/classification) — with confidence intervals - Python ML service (FastAPI, scikit-learn; R/sommer integration where needed) - Model versioning and experiment tracking (MLflow) - Big data processing (Parquet/DuckDB), CSV/VC', '{"source":"bionluk","source_id":861502,"category":"Yazılım & Teknoloji > Data Analizi & Raporlama","packages":[{"title":"Forecasting Dashboard","price":25000,"currency":"TRY","duration_days":7,"revisions":1,"description":"One ML forecasting model (regression/classification) for a single dataset + confidence intervals, results table and basic visualizations.","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]},{"title":"ML Analytics System","price":50000,"currency":"TRY","duration_days":15,"revisions":4,"description":"Everything in BASIC + 3 models, model versioning (MLflow), advanced visualizations (Manhattan/PCA/distribution) and CSV/VCF import.","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]},{"title":"Full AI Platform","price":100000,"currency":"TRY","duration_days":40,"revisions":8,"description":"Everything in STANDARD + unlimited models, automated retraining loop, AI/LLM interpretation layer and ranking/selection index.","options":[{"title":"Model Dokümantasyonu","value":true,"unit":null}]}],"html":"We build AI/ML-powered analytics and forecasting platforms that turn your data into predictions and decisions. End-to-end setup for R&D teams, agriculture/biotechnology organizations and data-intensive businesses.\\n\\nWHAT WE DELIVER\\n\\n- Machine learning prediction engine (regression/classification) — with confidence intervals\\n- Python ML service (FastAPI, scikit-learn; R/sommer integration where needed)\\n- Model versioning and experiment tracking (MLflow)\\n- Big data processing (Parquet/DuckDB), CSV/VCF import and data quality checks\\n- Interactive visualizations — distribution, bar, Manhattan/GWAS and PCA charts\\n- AI/LLM interpretation layer (Groq/OpenAI) — explains results in plain language\\n- Management dashboard: predictions, reporting, ranking/selection index\\n- Automated retraining loop and audit trail\\n\\nTECHNOLOGY\\n\\nFastify, Bun, TypeScript, Drizzle ORM, MySQL · Python, FastAPI, scikit-learn, MLflow · Next.js 16, Tailwind, Shadcn UI · Docker. Dedicated, standalone deployment for your organization.\\n\\nHOW WE WORK\\n\\n1) Defining your data and target metrics\\n2) Demo model + scope approval\\n3) Development, model training and validation\\n4) Dashboard delivery, training and go-live\\n\\nOur reference project is GenomAI — a genomic prediction (GEBV) and GWAS platform for plant breeding. Message us for a clear, project-specific proposal.","llms_summary":"AI & ML Data Forecasting Platform Development is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["Yazılım & Teknoloji","Data Analizi & Raporlama"]}', 'AI & ML Data Forecasting Platform Development', 'AI & ML Data Forecasting Platform Development | GZL Technology', 'We build AI/ML-powered analytics and forecasting platforms that turn your data into predictions and decisions. End-to-end setup for R&D teams, agriculture/biotechnology organizations and data-intensive businesses. WHAT WE DELIVER - Machine learning prediction engine (regression/classification) — with confidence intervals - Python ML service (FastAPI, scikit-learn; R/sommer integration where needed) - Model versioning and experiment tracking (MLflow) - Big data processing (Parquet/DuckDB), CSV/VC', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0005861509', '10000000-0000-4000-8000-0005861509', 'tr', 'amazon-fiyat-scraping-sistemi', ' Amazon ürün ve fiyat scraping sistemi geliştiririm', 'Merhaba! E-ticaret ve Amazon araştırması için veri toplayan (scraping) ve sonucu AI ile skorlayıp karara dönüştüren paneller geliştiriyorum. Ürün araştırması, fiyat takibi ve rakip analizi için uçtan uca sistem. ✅ NELER YAPIYORUM • Amazon / e-ticaret scraping (Oxylabs vb.) — arama sonucu, ürün detayı, ASIN tekilleştirme • Fiyat geçmişi zenginleştirme (Keepa) ve zaman serisi • Çok boyutlu risk/fırsat skorlama motoru • LLM cross-dimension reasoning — boyutları birleştirip açıklanabilir karar (AL /', '{"source":"bionluk","source_id":861509,"category":"İş & Yönetim > Pazar Araştırmaları","packages":[{"title":"Scraping Paneli","price":15000,"currency":"TRY","duration_days":7,"revisions":1,"description":"Tek site/kategori için scraping + sonuçları listeleyen panel. Arama, ürün detayı ve ASIN tekilleştirme, ","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":false,"unit":null},{"title":"Yönetici Özeti","value":false,"unit":null}]},{"title":"Skorlama Sistemi","price":25000,"currency":"TRY","duration_days":15,"revisions":3,"description":"TEMEL''in tümü + Keepa fiyat geçmişi, çok boyutlu risk/fırsat skorlama ve LLM destekli açıklanabilir karar","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":false,"unit":null},{"title":"Yönetici Özeti","value":false,"unit":null}]},{"title":"Tam Karar Radarı","price":50000,"currency":"TRY","duration_days":30,"revisions":5,"description":"STANDART''ın tümü + 5 boyut skor, coverage gate (confidence honesty), tez izleme ve bozulma uyarısı, çoklu","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":true,"unit":null},{"title":"Yönetici Özeti","value":true,"unit":null}]}],"html":"Merhaba! E-ticaret ve Amazon araştırması için veri toplayan (scraping) ve sonucu AI ile skorlayıp karara dönüştüren paneller geliştiriyorum. Ürün araştırması, fiyat takibi ve rakip analizi için uçtan uca sistem.\\n\\n✅ NELER YAPIYORUM\\n\\n• Amazon / e-ticaret scraping (Oxylabs vb.) — arama sonucu, ürün detayı, ASIN tekilleştirme\\n• Fiyat geçmişi zenginleştirme (Keepa) ve zaman serisi\\n• Çok boyutlu risk/fırsat skorlama motoru\\n• LLM cross-dimension reasoning — boyutları birleştirip açıklanabilir karar (AL / TAKİP / UZAK DUR)\\n• Confidence honesty: düşük/eksik veride \\"tahmini\\" dili + coverage kontrolü\\n• Karar/tez izleme — alınan kararlar bozulunca otomatik uyarı\\n• Operatör paneli: tek ekran tarama akışı, raporlama, kota görünürlüğü\\n• Scan cache reuse ve API kota yönetimi\\n\\n🛠️ TEKNOLOJİLER\\nTypeScript, Bun, Next.js 16, React, MySQL · Oxylabs, Keepa, Groq/OpenAI LLM. Size özel, bağımsız kurulum — API abonelikleri sizin hesabınızda kalır.\\n\\n🚀 NASIL ÇALIŞIYORUZ\\n1) Hedef pazar/veri ve karar kriteri belirleme\\n2) Demo tarama + kapsam onayı\\n3) Scraping + skorlama + panel geliştirme\\n4) Test, eğitim ve canlıya alma\\n\\nReferansım Amozon — Amazon Commercial Radar. Projenize özel net teklif için lütfen mesaj atın.","llms_summary":"GZL Teknoloji tarafından Amazon ürün ve fiyat scraping sistemi geliştiririm hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["İş & Yönetim","Pazar Araştırmaları"]}', ' Amazon ürün ve fiyat scraping sistemi geliştiririm', ' Amazon ürün ve fiyat scraping sistemi geliştiririm | GZL Teknoloji', 'Merhaba! E-ticaret ve Amazon araştırması için veri toplayan (scraping) ve sonucu AI ile skorlayıp karara dönüştüren paneller geliştiriyorum. Ürün araştırması, fiyat takibi ve rakip analizi için uçtan uca sistem. ✅ NELER YAPIYORUM • Amazon / e-ticaret scraping (Oxylabs vb.) — arama sonucu, ürün detayı, ASIN tekilleştirme • Fiyat geçmişi zenginleştirme (Keepa) ve zaman serisi • Çok boyutlu risk/fırsat skorlama motoru • LLM cross-dimension reasoning — boyutları birleştirip açıklanabilir karar (AL /', 'İş & Yönetim,Pazar Araştırmaları,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0005861509', '10000000-0000-4000-8000-0005861509', 'en', 'amazon-price-scraping-system', 'Amazon Product & Price Scraping System', 'We build dashboards for e-commerce and Amazon research that collect data (scraping), score it with AI and turn it into decisions. An end-to-end system for product research, price tracking and competitor analysis. WHAT WE DELIVER - Amazon / e-commerce scraping (Oxylabs and similar) — search results, product details, ASIN deduplication - Price history enrichment (Keepa) and time series - Multi-dimensional risk/opportunity scoring engine - LLM cross-dimension reasoning — combining dimensions into a', '{"source":"bionluk","source_id":861509,"category":"İş & Yönetim > Pazar Araştırmaları","packages":[{"title":"Scraping Dashboard","price":15000,"currency":"TRY","duration_days":7,"revisions":1,"description":"Scraping for a single site/category + a dashboard listing the results. Search, product details and ASIN deduplication.","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":false,"unit":null},{"title":"Yönetici Özeti","value":false,"unit":null}]},{"title":"Scoring System","price":25000,"currency":"TRY","duration_days":15,"revisions":3,"description":"Everything in BASIC + Keepa price history, multi-dimensional risk/opportunity scoring and LLM-assisted explainable decisions.","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":false,"unit":null},{"title":"Yönetici Özeti","value":false,"unit":null}]},{"title":"Full Decision Radar","price":50000,"currency":"TRY","duration_days":30,"revisions":5,"description":"Everything in STANDARD + 5-dimension scoring, coverage gate (confidence honesty), thesis tracking with degradation alerts.","options":[{"title":"Ticari Kaynak Kullanımı","value":true,"unit":null},{"title":"Ön Analiz","value":true,"unit":null},{"title":"Yönetici Özeti","value":true,"unit":null}]}],"html":"We build dashboards for e-commerce and Amazon research that collect data (scraping), score it with AI and turn it into decisions. An end-to-end system for product research, price tracking and competitor analysis.\\n\\nWHAT WE DELIVER\\n\\n- Amazon / e-commerce scraping (Oxylabs and similar) — search results, product details, ASIN deduplication\\n- Price history enrichment (Keepa) and time series\\n- Multi-dimensional risk/opportunity scoring engine\\n- LLM cross-dimension reasoning — combining dimensions into an explainable decision (BUY / WATCH / AVOID)\\n- Confidence honesty: hedged \\"estimated\\" language plus coverage checks when data is thin or missing\\n- Decision/thesis tracking — automatic alerts when the premise behind a decision breaks down\\n- Operator dashboard: single-screen scan flow, reporting, quota visibility\\n- Scan cache reuse and API quota management\\n\\nTECHNOLOGY\\n\\nTypeScript, Bun, Next.js 16, React, MySQL · Oxylabs, Keepa, Groq/OpenAI LLM. Dedicated, standalone deployment — API subscriptions remain in your own accounts.\\n\\nHOW WE WORK\\n\\n1) Defining your target market/data and decision criteria\\n2) Demo scan + scope approval\\n3) Scraping + scoring + dashboard development\\n4) Testing, training and go-live\\n\\nOur reference is Amozon — Amazon Commercial Radar. Message us for a clear, project-specific proposal.","llms_summary":"Amazon Product & Price Scraping System is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["İş & Yönetim","Pazar Araştırmaları"]}', 'Amazon Product & Price Scraping System', 'Amazon Product & Price Scraping System | GZL Technology', 'We build dashboards for e-commerce and Amazon research that collect data (scraping), score it with AI and turn it into decisions. An end-to-end system for product research, price tracking and competitor analysis. WHAT WE DELIVER - Amazon / e-commerce scraping (Oxylabs and similar) — search results, product details, ASIN deduplication - Price history enrichment (Keepa) and time series - Multi-dimensional risk/opportunity scoring engine - LLM cross-dimension reasoning — combining dimensions into a', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0006861515', '10000000-0000-4000-8000-0006861515', 'tr', 'yapay-zeka-arama-optimizasyonu-geo', 'sitenizi chatgpt ve ai aramaları için optimize ederim', 'Merhaba! Artık insanlar Google''ın yanında ChatGPT, Perplexity, Gemini ve Google AI Overviews ile arama yapıyor. Sitenizin bu yapay zeka motorları tarafından bulunup ALINTILANMASI için GEO (Generative Engine Optimization) + klasik SEO çalışması yapıyorum. ✅ NELER YAPIYORUM • GEO + SEO denetimi — 6 boyutlu skor (citability, teknik SEO, schema, E-E-A-T, AI crawler, performans) • AI platform hazırlığı analizi — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot • AI crawler erişimi (GPTBot, Per', '{"source":"bionluk","source_id":861515,"category":"İnternet Reklamcılığı > Diğer İnternet Reklamcılığı","packages":[{"title":"GEO + SEO Analiz","price":250,"currency":"TRY","duration_days":1,"revisions":0,"description":"Sitenizin yapay zeka aramalarına hazırlık analizi: 6 boyutlu GEO+SEO skoru, AI platform hazırlığı, AI cra","options":[]},{"title":"Analiz + Uygulama","price":2000,"currency":"TRY","duration_days":1,"revisions":0,"description":"TEMEL''in tümü + uygulama: Schema.org/JSON-LD, llms.txt, AI crawler erişimi düzeni, teknik SEO ve CWV iyil","options":[]},{"title":"Tam GEO + SEO + İzleme","price":5000,"currency":"TRY","duration_days":7,"revisions":0,"description":"STANDART''ın tümü + tüm site kapsamı, E-E-A-T ve marka anması çalışması, içerik uygulaması, 30/60/90 yol h","options":[]}],"html":"Merhaba! Artık insanlar Google''ın yanında ChatGPT, Perplexity, Gemini ve Google AI Overviews ile arama yapıyor. Sitenizin bu yapay zeka motorları tarafından bulunup ALINTILANMASI için GEO (Generative Engine Optimization) + klasik SEO çalışması yapıyorum.\\n\\n✅ NELER YAPIYORUM\\n\\n• GEO + SEO denetimi — 6 boyutlu skor (citability, teknik SEO, schema, E-E-A-T, AI crawler, performans)\\n• AI platform hazırlığı analizi — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot\\n• AI crawler erişimi (GPTBot, PerplexityBot, Google-Extended, ClaudeBot) — robots/meta düzeni\\n• Schema.org / JSON-LD yapısal veri (Article, FAQ, LocalBusiness, Breadcrumb)\\n• llms.txt oluşturma ve yayınlama\\n• Alıntılanabilir içerik — net cevap blokları, TL;DR özetler, FAQ\\n• Teknik SEO + Core Web Vitals (LCP, CLS, INP) iyileştirme\\n• E-E-A-T güven sinyalleri ve marka anması (entity) çalışması\\n• PDF rapor + önceliklendirilmiş 30/60/90 aksiyon planı\\n\\n🛠️ NASIL ÇALIŞIYORUZ\\n1) Ücretsiz ön analiz + GEO/SEO skoru\\n2) Detaylı rapor ve kapsam onayı\\n3) Uygulama (implementation) — teknik + içerik\\n4) Doğrulama, izleme ve raporlama\\n\\nKendi GEO/SEO analiz platformum GeoSerra ile çalışıyorum. Site türünüze göre net teklif için mesaj atın.","llms_summary":"GZL Teknoloji tarafından sitenizi chatgpt ve ai aramaları için optimize ederim hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["İnternet Reklamcılığı","Diğer İnternet Reklamcılığı"]}', 'sitenizi chatgpt ve ai aramaları için optimize ederim', 'sitenizi chatgpt ve ai aramaları için optimize ederim | GZL Teknoloji', 'Merhaba! Artık insanlar Google''ın yanında ChatGPT, Perplexity, Gemini ve Google AI Overviews ile arama yapıyor. Sitenizin bu yapay zeka motorları tarafından bulunup ALINTILANMASI için GEO (Generative Engine Optimization) + klasik SEO çalışması yapıyorum. ✅ NELER YAPIYORUM • GEO + SEO denetimi — 6 boyutlu skor (citability, teknik SEO, schema, E-E-A-T, AI crawler, performans) • AI platform hazırlığı analizi — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot • AI crawler erişimi (GPTBot, Per', 'İnternet Reklamcılığı,Diğer İnternet Reklamcılığı,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0006861515', '10000000-0000-4000-8000-0006861515', 'en', 'generative-engine-optimization-geo', 'Generative Engine Optimization (GEO) — Get Cited by ChatGPT & AI Search', 'People now search with ChatGPT, Perplexity, Gemini and Google AI Overviews alongside Google. We combine GEO (Generative Engine Optimization) with classic SEO so that your site gets found — and CITED — by these AI engines. WHAT WE DELIVER - GEO + SEO audit — 6-dimension score (citability, technical SEO, schema, E-E-A-T, AI crawlers, performance) - AI platform readiness analysis — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot - AI crawler access (GPTBot, PerplexityBot, Google-Extended, C', '{"source":"bionluk","source_id":861515,"category":"İnternet Reklamcılığı > Diğer İnternet Reklamcılığı","packages":[{"title":"GEO + SEO Audit","price":250,"currency":"TRY","duration_days":1,"revisions":0,"description":"AI-search readiness analysis of your site: 6-dimension GEO+SEO score, AI platform readiness and AI crawler access review.","options":[]},{"title":"Audit + Implementation","price":2000,"currency":"TRY","duration_days":1,"revisions":0,"description":"Everything in BASIC + implementation: Schema.org/JSON-LD, llms.txt, AI crawler access configuration, technical SEO and Core Web Vitals improvements.","options":[]},{"title":"Full GEO + SEO + Monitoring","price":5000,"currency":"TRY","duration_days":7,"revisions":0,"description":"Everything in STANDARD + full-site coverage, E-E-A-T and brand mention (entity) work, content implementation and a 30/60/90-day roadmap.","options":[]}],"html":"People now search with ChatGPT, Perplexity, Gemini and Google AI Overviews alongside Google. We combine GEO (Generative Engine Optimization) with classic SEO so that your site gets found — and CITED — by these AI engines.\\n\\nWHAT WE DELIVER\\n\\n- GEO + SEO audit — 6-dimension score (citability, technical SEO, schema, E-E-A-T, AI crawlers, performance)\\n- AI platform readiness analysis — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot\\n- AI crawler access (GPTBot, PerplexityBot, Google-Extended, ClaudeBot) — robots/meta configuration\\n- Schema.org / JSON-LD structured data (Article, FAQ, LocalBusiness, Breadcrumb)\\n- llms.txt creation and publishing\\n- Citable content — clear answer blocks, TL;DR summaries, FAQs\\n- Technical SEO + Core Web Vitals (LCP, CLS, INP) improvements\\n- E-E-A-T trust signals and brand mention (entity) work\\n- PDF report + prioritized 30/60/90-day action plan\\n\\nHOW WE WORK\\n\\n1) Free preliminary analysis + GEO/SEO score\\n2) Detailed report and scope approval\\n3) Implementation — technical + content\\n4) Verification, monitoring and reporting\\n\\nWe run this work on GeoSerra, our own GEO/SEO analysis platform. Message us for a quote tailored to your site type.","llms_summary":"Generative Engine Optimization (GEO) — Get Cited by ChatGPT & AI Search is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["İnternet Reklamcılığı","Diğer İnternet Reklamcılığı"]}', 'Generative Engine Optimization (GEO) — Get Cited by ChatGPT & AI Search', 'Generative Engine Optimization (GEO) — Get Cited by ChatGPT & AI Search | GZL Technology', 'People now search with ChatGPT, Perplexity, Gemini and Google AI Overviews alongside Google. We combine GEO (Generative Engine Optimization) with classic SEO so that your site gets found — and CITED — by these AI engines. WHAT WE DELIVER - GEO + SEO audit — 6-dimension score (citability, technical SEO, schema, E-E-A-T, AI crawlers, performance) - AI platform readiness analysis — ChatGPT, Perplexity, Gemini, AI Overviews, Bing Copilot - AI crawler access (GPTBot, PerplexityBot, Google-Extended, C', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0007861532', '10000000-0000-4000-8000-0007861532', 'tr', 'ga4-gtm-donusum-izleme', 'sitenize GA4, GTM ve dönüşüm izleme kurulumu yaparım', 'Merhaba! Web sitenize doğru veri toplama ve dönüşüm izleme kurulumu yapıyorum: hangi kanaldan kaç satış/lead geldiğini, reklamlarınızın gerçek ROAS''ını net görürsünüz. ✅ NELER YAPIYORUM • Google Analytics 4 (GA4) kurulumu ve doğru olay/dönüşüm yapılandırması • Google Tag Manager (GTM) container kurulumu ve etiket yönetimi • Meta (Facebook/Instagram) Pixel + Conversions API (server-side) • Google Ads dönüşüm izleme + GA4 içe aktarımı • E-ticaret satın alma & gelir izleme (enhanced e-commerce / pu', '{"source":"bionluk","source_id":861532,"category":"İnternet Reklamcılığı > Web Analytics & İzleme","packages":[{"title":"GA4 + GTM Kurulum","price":1000,"currency":"TRY","duration_days":1,"revisions":0,"description":"Google Analytics 4 ve Google Tag Manager kurulumu, temel sayfa görüntüleme ve 1-2 dönüşüm olayı yapılandı","options":[]},{"title":"Dönüşüm İzleme","price":2500,"currency":"TRY","duration_days":1,"revisions":0,"description":"TEMEL''in tümü + Meta Pixel, Google Ads dönüşüm izleme, e-ticaret satın alma/gelir event''leri ve 5''e kadar","options":[]},{"title":"Tam Tracking Sistemi","price":5000,"currency":"TRY","duration_days":10,"revisions":0,"description":"STANDART''ın tümü + Meta Conversions API (server-side), sGTM, Consent Mode v2 (KVKK/GDPR), kanal/atıf & RO","options":[]}],"html":"Merhaba! Web sitenize doğru veri toplama ve dönüşüm izleme kurulumu yapıyorum: hangi kanaldan kaç satış/lead geldiğini, reklamlarınızın gerçek ROAS''ını net görürsünüz.\\n\\n✅ NELER YAPIYORUM\\n\\n• Google Analytics 4 (GA4) kurulumu ve doğru olay/dönüşüm yapılandırması\\n• Google Tag Manager (GTM) container kurulumu ve etiket yönetimi\\n• Meta (Facebook/Instagram) Pixel + Conversions API (server-side)\\n• Google Ads dönüşüm izleme + GA4 içe aktarımı\\n• E-ticaret satın alma & gelir izleme (enhanced e-commerce / purchase event)\\n• Dönüşüm hunisi (funnel) ve event tabanlı izleme\\n• Consent Mode v2 (KVKK/GDPR çerez onayı) uyumu\\n• Server-side tracking (sGTM) ile veri kaybını azaltma\\n• Kanal / atıf (attribution) ve ROAS raporlama kurulumu\\n• Test, doğrulama (DebugView, Tag Assistant) ve kısa kullanım eğitimi\\n\\n🛠️ NASIL ÇALIŞIYORUZ\\n1) Mevcut kurulumun denetimi + hedef dönüşümlerin belirlenmesi\\n2) GTM/GA4/Pixel/Ads yapılandırması\\n3) Test, doğrulama ve canlıya alma\\n4) Raporlama kurulumu + eğitim\\n\\nWordPress, Shopify, Ticimax, İkas, özel yazılım ve çoğu altyapıda çalışırım. Net teklif için mesaj atın.","llms_summary":"GZL Teknoloji tarafından sitenize GA4, GTM ve dönüşüm izleme kurulumu yaparım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["İnternet Reklamcılığı","Web Analytics & İzleme"]}', 'sitenize GA4, GTM ve dönüşüm izleme kurulumu yaparım', 'sitenize GA4, GTM ve dönüşüm izleme kurulumu yaparım | GZL Teknoloji', 'Merhaba! Web sitenize doğru veri toplama ve dönüşüm izleme kurulumu yapıyorum: hangi kanaldan kaç satış/lead geldiğini, reklamlarınızın gerçek ROAS''ını net görürsünüz. ✅ NELER YAPIYORUM • Google Analytics 4 (GA4) kurulumu ve doğru olay/dönüşüm yapılandırması • Google Tag Manager (GTM) container kurulumu ve etiket yönetimi • Meta (Facebook/Instagram) Pixel + Conversions API (server-side) • Google Ads dönüşüm izleme + GA4 içe aktarımı • E-ticaret satın alma & gelir izleme (enhanced e-commerce / pu', 'İnternet Reklamcılığı,Web Analytics & İzleme,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0007861532', '10000000-0000-4000-8000-0007861532', 'en', 'ga4-gtm-conversion-tracking', 'GA4, GTM & Conversion Tracking Setup', 'We set up accurate data collection and conversion tracking on your website, so you can see exactly how many sales or leads each channel brings in — and the real ROAS of your ads. WHAT WE DELIVER - Google Analytics 4 (GA4) setup with correct event/conversion configuration - Google Tag Manager (GTM) container setup and tag management - Meta (Facebook/Instagram) Pixel + Conversions API (server-side) - Google Ads conversion tracking + GA4 import - E-commerce purchase & revenue tracking (enhanced e-c', '{"source":"bionluk","source_id":861532,"category":"İnternet Reklamcılığı > Web Analytics & İzleme","packages":[{"title":"GA4 + GTM Setup","price":1000,"currency":"TRY","duration_days":1,"revisions":0,"description":"Google Analytics 4 and Google Tag Manager setup, with basic page-view tracking and configuration of 1–2 conversion events.","options":[]},{"title":"Conversion Tracking","price":2500,"currency":"TRY","duration_days":1,"revisions":0,"description":"Everything in BASIC + Meta Pixel, Google Ads conversion tracking, e-commerce purchase/revenue events and up to 5 conversion events.","options":[]},{"title":"Full Tracking System","price":5000,"currency":"TRY","duration_days":10,"revisions":0,"description":"Everything in STANDARD + Meta Conversions API (server-side), sGTM, Consent Mode v2 (KVKK/GDPR) and channel/attribution & ROAS reporting.","options":[]}],"html":"We set up accurate data collection and conversion tracking on your website, so you can see exactly how many sales or leads each channel brings in — and the real ROAS of your ads.\\n\\nWHAT WE DELIVER\\n\\n- Google Analytics 4 (GA4) setup with correct event/conversion configuration\\n- Google Tag Manager (GTM) container setup and tag management\\n- Meta (Facebook/Instagram) Pixel + Conversions API (server-side)\\n- Google Ads conversion tracking + GA4 import\\n- E-commerce purchase & revenue tracking (enhanced e-commerce / purchase event)\\n- Conversion funnels and event-based tracking\\n- Consent Mode v2 (KVKK/GDPR cookie consent) compliance\\n- Server-side tracking (sGTM) to reduce data loss\\n- Channel / attribution and ROAS reporting setup\\n- Testing, verification (DebugView, Tag Assistant) and a short usage training\\n\\nHOW WE WORK\\n\\n1) Audit of the current setup + defining target conversions\\n2) GTM/GA4/Pixel/Ads configuration\\n3) Testing, verification and go-live\\n4) Reporting setup + training\\n\\nWe work with WordPress, Shopify, Ticimax, Ikas, custom builds and most other platforms. Message us for a clear quote.","llms_summary":"GA4, GTM & Conversion Tracking Setup is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["İnternet Reklamcılığı","Web Analytics & İzleme"]}', 'GA4, GTM & Conversion Tracking Setup', 'GA4, GTM & Conversion Tracking Setup | GZL Technology', 'We set up accurate data collection and conversion tracking on your website, so you can see exactly how many sales or leads each channel brings in — and the real ROAS of your ads. WHAT WE DELIVER - Google Analytics 4 (GA4) setup with correct event/conversion configuration - Google Tag Manager (GTM) container setup and tag management - Meta (Facebook/Instagram) Pixel + Conversions API (server-side) - Google Ads conversion tracking + GA4 import - E-commerce purchase & revenue tracking (enhanced e-c', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0008861536', '10000000-0000-4000-8000-0008861536', 'tr', 'google-maps-veri-cekme-botu', 'Google Maps ve sitelerden veri çekme botu yazarım', 'Merhaba! Web sitelerinden, Google Maps''ten ve B2B dizinlerden ihtiyacınız olan veriyi çeken (web scraping) sistemler geliştiriyorum. İster hazır bir API, ister tek seferlik veri çıkarımı. ✅ NELER YAPIYORUM • Web scraping API / mikro-servis (Python · FastAPI) • Playwright stealth modu ile dinamik (JS''li) sayfalardan veri çekme • Cloudflare / bot korumalı sitelerde çalışan çözümler • Google Maps işletme verisi (isim, telefon, adres, puan, URL) • B2B dizin, fuar katılımcısı ve rakip sitesi tarama p', '{"source":"bionluk","source_id":861536,"category":"Yazılım & Teknoloji > Data Analizi & Raporlama","packages":[{"title":"Tek Seferlik Veri","price":1500,"currency":"TRY","duration_days":1,"revisions":0,"description":"Tek site veya Google Maps aramasından ihtiyacınız olan verinin (isim, telefon, adres, fiyat vb.) çekilip ","options":[]},{"title":"Özel Scraping Botu","price":4000,"currency":"TRY","duration_days":2,"revisions":0,"description":"1-3 site için yeniden çalıştırılabilir özel scraping scripti: dinamik (JS) sayfa desteği, stealth, zamanl","options":[]},{"title":"Scraping API Sistemi","price":9000,"currency":"TRY","duration_days":7,"revisions":0,"description":"Çok kaynaklı, üretime hazır scraping API: FastAPI uç noktaları, async job kuyruğu (arq) + HMAC webhook, P","options":[]}],"html":"Merhaba! Web sitelerinden, Google Maps''ten ve B2B dizinlerden ihtiyacınız olan veriyi çeken (web scraping) sistemler geliştiriyorum. İster hazır bir API, ister tek seferlik veri çıkarımı.\\n\\n✅ NELER YAPIYORUM\\n\\n• Web scraping API / mikro-servis (Python · FastAPI)\\n• Playwright stealth modu ile dinamik (JS''li) sayfalardan veri çekme\\n• Cloudflare / bot korumalı sitelerde çalışan çözümler\\n• Google Maps işletme verisi (isim, telefon, adres, puan, URL)\\n• B2B dizin, fuar katılımcısı ve rakip sitesi tarama profilleri\\n• E-ticaret ürün/fiyat takibi ve değişiklik izleme\\n• Senkron + asenkron job kuyruğu (arq) ve webhook callback (HMAC imzalı)\\n• Redis cache, Bearer token auth ve günlük kota yönetimi\\n• CSV / JSON / Excel çıktısı veya doğrudan API entegrasyonu\\n• Docker ile kendi sunucunuza kurulum\\n\\n🛠️ TEKNOLOJİLER\\nPython, FastAPI, Scrapling, Playwright, Redis, arq, Docker.\\n\\n🚀 NASIL ÇALIŞIYORUZ\\n1) Hedef site/veri ve alanların belirlenmesi\\n2) Örnek çıktı (demo) + kapsam onayı\\n3) Geliştirme, test ve teslim\\n4) İsterseniz sunucuya kurulum + bakım\\n\\nNot: Yalnızca herkese açık ve toplamaya hakkınız olan verilerle, ilgili sitenin şartlarına uygun çalışırım. Kapsam için mesaj atın.","llms_summary":"GZL Teknoloji tarafından Google Maps ve sitelerden veri çekme botu yazarım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["Yazılım & Teknoloji","Data Analizi & Raporlama"]}', 'Google Maps ve sitelerden veri çekme botu yazarım', 'Google Maps ve sitelerden veri çekme botu yazarım | GZL Teknoloji', 'Merhaba! Web sitelerinden, Google Maps''ten ve B2B dizinlerden ihtiyacınız olan veriyi çeken (web scraping) sistemler geliştiriyorum. İster hazır bir API, ister tek seferlik veri çıkarımı. ✅ NELER YAPIYORUM • Web scraping API / mikro-servis (Python · FastAPI) • Playwright stealth modu ile dinamik (JS''li) sayfalardan veri çekme • Cloudflare / bot korumalı sitelerde çalışan çözümler • Google Maps işletme verisi (isim, telefon, adres, puan, URL) • B2B dizin, fuar katılımcısı ve rakip sitesi tarama p', 'Yazılım & Teknoloji,Data Analizi & Raporlama,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0008861536', '10000000-0000-4000-8000-0008861536', 'en', 'google-maps-data-scraping-bot', 'Google Maps & Website Data Scraping Bot', 'We build web scraping systems that extract the data you need from websites, Google Maps and B2B directories — whether you need a ready-to-use API or a one-time data extraction. WHAT WE DELIVER - Web scraping API / microservice (Python · FastAPI) - Data extraction from dynamic (JavaScript-rendered) pages with Playwright stealth mode - Solutions that work on Cloudflare and bot-protected sites - Google Maps business data (name, phone, address, rating, URL) - Scan profiles for B2B directories, trade', '{"source":"bionluk","source_id":861536,"category":"Yazılım & Teknoloji > Data Analizi & Raporlama","packages":[{"title":"One-Time Data Extraction","price":1500,"currency":"TRY","duration_days":1,"revisions":0,"description":"The data you need (name, phone, address, price, etc.) extracted from a single website or Google Maps search and delivered.","options":[]},{"title":"Custom Scraping Bot","price":4000,"currency":"TRY","duration_days":2,"revisions":0,"description":"A re-runnable custom scraping script for 1–3 sites: dynamic (JS) page support, stealth mode and scheduling.","options":[]},{"title":"Scraping API System","price":9000,"currency":"TRY","duration_days":7,"revisions":0,"description":"A multi-source, production-ready scraping API: FastAPI endpoints, async job queue (arq) + HMAC webhooks and Playwright support.","options":[]}],"html":"We build web scraping systems that extract the data you need from websites, Google Maps and B2B directories — whether you need a ready-to-use API or a one-time data extraction.\\n\\nWHAT WE DELIVER\\n\\n- Web scraping API / microservice (Python · FastAPI)\\n- Data extraction from dynamic (JavaScript-rendered) pages with Playwright stealth mode\\n- Solutions that work on Cloudflare and bot-protected sites\\n- Google Maps business data (name, phone, address, rating, URL)\\n- Scan profiles for B2B directories, trade fair exhibitors and competitor sites\\n- E-commerce product/price tracking and change monitoring\\n- Synchronous + asynchronous job queue (arq) and webhook callbacks (HMAC-signed)\\n- Redis cache, Bearer token auth and daily quota management\\n- CSV / JSON / Excel output or direct API integration\\n- Deployment to your own server with Docker\\n\\nTECHNOLOGY\\n\\nPython, FastAPI, Scrapling, Playwright, Redis, arq, Docker.\\n\\nHOW WE WORK\\n\\n1) Defining target sites/data and fields\\n2) Sample output (demo) + scope approval\\n3) Development, testing and delivery\\n4) Optional server deployment + maintenance\\n\\nNote: we only work with publicly available data that you are entitled to collect, in accordance with the target site''s terms. Message us with your scope.","llms_summary":"Google Maps & Website Data Scraping Bot is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["Yazılım & Teknoloji","Data Analizi & Raporlama"]}', 'Google Maps & Website Data Scraping Bot', 'Google Maps & Website Data Scraping Bot | GZL Technology', 'We build web scraping systems that extract the data you need from websites, Google Maps and B2B directories — whether you need a ready-to-use API or a one-time data extraction. WHAT WE DELIVER - Web scraping API / microservice (Python · FastAPI) - Data extraction from dynamic (JavaScript-rendered) pages with Playwright stealth mode - Solutions that work on Cloudflare and bot-protected sites - Google Maps business data (name, phone, address, rating, URL) - Scan profiles for B2B directories, trade', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0009861114', '10000000-0000-4000-8000-0009861114', 'tr', 'firmaya-ozel-erp-yazilimi', 'firmanıza özel ERP ve yönetim sistemi yazarım', 'İşletmenizi tek bir panelden yönetmek ister misiniz? Stok, sipariş, üretim, cari, fatura ve raporlamayı bir araya getiren, işinize özel ERP yazılımları geliştiriyorum. Hazır şablon değil; sizin iş akışınıza göre kurgulanan, büyüdükçe büyüyen bir sistem. Production seviyesinde, çok kullanıcılı kurumsal sistemler geliştirdiğim için ERP''nin en zor taraflarını (çok kullanıcılı veri tutarlılığı, yetkilendirme, gerçek zamanlı senkronizasyon) baştan doğru kuruyorum. Geliştirdiğim modüller (ihtiyaca gör', '{"source":"bionluk","source_id":861114,"category":"Yazılım & Teknoloji > Diğer Yazılım Teknoloji","packages":[{"title":"\\tÇekirdek ERP","price":30000,"currency":"TRY","duration_days":15,"revisions":1,"description":"Stok + sipariş + cari + yönetim paneli. Çok kullanıcılı temel ERP, canlıya alma dahil.","options":[]},{"title":"Genişletilmiş ERP","price":60000,"currency":"TRY","duration_days":30,"revisions":3,"description":"Çekirdek ERP + üretim/iş emri + fatura + raporlama + Excel dışa aktarma.","options":[]},{"title":"\\tTam ERP Sistemi","price":100000,"currency":"TRY","duration_days":45,"revisions":5,"description":"Tam ERP: tüm modüller + çok kullanıcılı yetkilendirme + bildirim sistemi + raporlama + canlıya alma ","options":[]}],"html":"İşletmenizi tek bir panelden yönetmek ister misiniz? Stok, sipariş, üretim, cari, fatura ve raporlamayı bir araya getiren, işinize özel ERP yazılımları geliştiriyorum. Hazır şablon değil; sizin iş akışınıza göre kurgulanan, büyüdükçe büyüyen bir sistem.\\n\\nProduction seviyesinde, çok kullanıcılı kurumsal sistemler geliştirdiğim için ERP''nin en zor taraflarını (çok kullanıcılı veri tutarlılığı, yetkilendirme, gerçek zamanlı senkronizasyon) baştan doğru kuruyorum.\\n\\nGeliştirdiğim modüller (ihtiyaca göre):\\n• Stok ve depo yönetimi (kritik stok uyarıları dahil)\\n• Sipariş, satış ve satın alma takibi\\n• Üretim / iş emri planlama\\n• Cari hesap, fatura ve ödeme takibi\\n• Kullanıcı rolleri ve yetkilendirme (çok kullanıcılı)\\n• Bildirim sistemi (uygulama içi / e-posta)\\n• Raporlama ve Excel dışa aktarma\\n• Yönetim paneli (admin) ve mobil uyumlu arayüz\\n\\nTeknik altyapı: Next.js + React, Fastify / Node.js, Drizzle ORM, PostgreSQL / Supabase veya MySQL. Sunucu kurulumu ve canlıya alma (VPS, Nginx) tarafını da ben hallederim; ürün size çalışır halde teslim edilir.\\n\\nÇalışma şeklim: Önce ihtiyaç analizini yapıp net bir kapsam ve teslim planı çıkarırım. Geliştirme sırasında düzenli olarak çalışan bir önizleme paylaşır, birlikte ilerleriz. Teslim sonrası hata düzeltme ve devam eden geliştirme için de buradayım.\\n\\nİşletmenizi ve ihtiyaçlarınızı kısaca mesajla anlatın; size özel kapsam, süre ve fiyat çıkaralım.","llms_summary":"GZL Teknoloji tarafından firmanıza özel ERP ve yönetim sistemi yazarım hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["Yazılım & Teknoloji","Diğer Yazılım Teknoloji"]}', 'firmanıza özel ERP ve yönetim sistemi yazarım', 'firmanıza özel ERP ve yönetim sistemi yazarım | GZL Teknoloji', 'İşletmenizi tek bir panelden yönetmek ister misiniz? Stok, sipariş, üretim, cari, fatura ve raporlamayı bir araya getiren, işinize özel ERP yazılımları geliştiriyorum. Hazır şablon değil; sizin iş akışınıza göre kurgulanan, büyüdükçe büyüyen bir sistem. Production seviyesinde, çok kullanıcılı kurumsal sistemler geliştirdiğim için ERP''nin en zor taraflarını (çok kullanıcılı veri tutarlılığı, yetkilendirme, gerçek zamanlı senkronizasyon) baştan doğru kuruyorum. Geliştirdiğim modüller (ihtiyaca gör', 'Yazılım & Teknoloji,Diğer Yazılım Teknoloji,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0009861114', '10000000-0000-4000-8000-0009861114', 'en', 'custom-erp-software', 'Custom ERP & Business Management Software', 'Would you like to run your entire business from a single dashboard? We develop custom ERP software that brings inventory, orders, production, accounts, invoicing and reporting together — not an off-the-shelf template, but a system designed around your workflow that grows as you do. Because we build production-grade, multi-user enterprise systems, we get the hardest parts of ERP right from the start: multi-user data consistency, authorization and real-time synchronization. MODULES WE BUILD (AS NE', '{"source":"bionluk","source_id":861114,"category":"Yazılım & Teknoloji > Diğer Yazılım Teknoloji","packages":[{"title":"Core ERP","price":30000,"currency":"TRY","duration_days":15,"revisions":1,"description":"Inventory + orders + accounts + admin panel. Multi-user core ERP, production deployment included.","options":[]},{"title":"Extended ERP","price":60000,"currency":"TRY","duration_days":30,"revisions":3,"description":"Core ERP + production/work orders + invoicing + reporting + Excel export.","options":[]},{"title":"Full ERP System","price":100000,"currency":"TRY","duration_days":45,"revisions":5,"description":"Complete ERP: all modules + multi-user authorization + notification system + reporting + production deployment.","options":[]}],"html":"Would you like to run your entire business from a single dashboard? We develop custom ERP software that brings inventory, orders, production, accounts, invoicing and reporting together — not an off-the-shelf template, but a system designed around your workflow that grows as you do.\\n\\nBecause we build production-grade, multi-user enterprise systems, we get the hardest parts of ERP right from the start: multi-user data consistency, authorization and real-time synchronization.\\n\\nMODULES WE BUILD (AS NEEDED)\\n\\n- Inventory and warehouse management (including critical stock alerts)\\n- Order, sales and purchasing tracking\\n- Production / work order planning\\n- Accounts, invoicing and payment tracking\\n- User roles and permissions (multi-user)\\n- Notification system (in-app / email)\\n- Reporting and Excel export\\n- Admin panel and mobile-friendly interface\\n\\nTECHNOLOGY\\n\\nNext.js + React, Fastify / Node.js, Drizzle ORM, PostgreSQL / Supabase or MySQL. We also handle server setup and go-live (VPS, Nginx); the product is delivered up and running.\\n\\nHOW WE WORK\\n\\nWe start with a requirements analysis and produce a clear scope and delivery plan. During development we regularly share a working preview and move forward together. After delivery, we remain available for bug fixes and ongoing development.\\n\\nTell us briefly about your business and your needs, and we will prepare a scope, timeline and price tailored to you.","llms_summary":"Custom ERP & Business Management Software is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["Yazılım & Teknoloji","Diğer Yazılım Teknoloji"]}', 'Custom ERP & Business Management Software', 'Custom ERP & Business Management Software | GZL Technology', 'Would you like to run your entire business from a single dashboard? We develop custom ERP software that brings inventory, orders, production, accounts, invoicing and reporting together — not an off-the-shelf template, but a system designed around your workflow that grows as you do. Because we build production-grade, multi-user enterprise systems, we get the hardest parts of ERP right from the start: multi-user data consistency, authorization and real-time synchronization. MODULES WE BUILD (AS NE', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000001-0000-4000-8000-0010796863', '10000000-0000-4000-8000-0010796863', 'tr', 'online-siparis-sistemi', 'online sipariş sistemi kurarım', 'Next.js (App Router) + TypeScript + Express + MongoDB ile restoranınıza özel, çok dilli QR menü ve online sipariş altyapısı kurarım. Modüller: kategori/ürün, varyant & ekstra, sepet/kupon, teslimat–paket servis, kurye akışı, yönetim paneli ve raporlar. Mobil ve SEO uyumlu, performans odaklı ve güvenli (HTTP-only cookie). Teslim: canlı demo, kaynak kod (GitHub), kısa dokümantasyon ve kurulum desteği. Opsiyonel: ödeme entegrasyonu (iyzico/Stripe), çok şube, WhatsApp sipariş butonu. 4 revizyon dahi', '{"source":"bionluk","source_id":796863,"category":"Yazılım & Teknoloji > Web Yazılım","packages":[{"title":"Temel — QR Menü + Basit Sepet","price":30000,"currency":"TRY","duration_days":10,"revisions":1,"description":"Tek şube, tek dil. QR menü, ürün–varyant–ekstra yönetimi ve basit sepet. Standart tema, mobil/SEO uyumlu.","options":[{"title":"Sayfa Sayısı","value":6,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":false,"unit":null}]},{"title":"Standart — Sepet + Kupon + Çok Dilli","price":40000,"currency":"TRY","duration_days":14,"revisions":2,"description":"Tek/çok şube, 2 dil (TR+EN/DE). Sepet + kupon, teslimat–paket servis ayarları, temel raporlar. Tema renk/","options":[{"title":"Sayfa Sayısı","value":10,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":false,"unit":null}]},{"title":"Pro — Çok Şube + Kurye + Ödeme","price":50000,"currency":"TRY","duration_days":21,"revisions":3,"description":"Çok şube + bölge, kurye/teslimat akışı, kupon/kampanya, gelişmiş raporlar. Özel bileşen tasarımı. Ödeme","options":