('10000001-0000-4000-8000-0016840182', '10000000-0000-4000-8000-0016840182', 'tr', 'randevu-sistemli-kurumsal-site', 'randevu sistemli kurumsal web siteleri geliştiririm', 'Klinik, spa, güzellik merkezi ve sağlık profesyonelleri için modern kurumsal web siteleri geliştiriyorum. Online randevu alma modülü, takvim entegrasyonu, çok dilli destek ve yapay zeka destekli sohbet botu (AI chatbot) dahil uçtan uca fullstack çözümler sunuyorum. Müşterileriniz 7/24 randevu alabilir, siz de tüm süreci admin panelinden yönetebilirsiniz.', '{"source":"bionluk","source_id":840182,"category":"Yazılım & Teknoloji > Web Yazılım","packages":[{"title":"Başlangıç Paketi","price":5000,"currency":"TRY","duration_days":7,"revisions":2,"description":"Tek dilli kurumsal tanıtım sitesi. Hizmet sayfaları ve iletişim formu dahil","options":[{"title":"Sayfa Sayısı","value":7,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":false,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":"Profesyonel Paket","price":10000,"currency":"TRY","duration_days":15,"revisions":5,"description":"Çok dilli kurumsal site + online randevu alma sistemi ve takvim yönetimi dahil.","options":[{"title":"Sayfa Sayısı","value":10,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":" Kurumsal Paket","price":20000,"currency":"TRY","duration_days":30,"revisions":7,"description":"Çok dilli kurumsal site + online randevu sistemi + yapay zeka destekli sohbet botu (AI Chatbot). Admin pa","options":[{"title":"Sayfa Sayısı","value":15,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]}],"html":"Klinik, spa, güzellik merkezi ve sağlık profesyonelleri için modern kurumsal web siteleri geliştiriyorum. Online randevu alma modülü, takvim entegrasyonu, çok dilli destek ve yapay zeka destekli sohbet botu (AI chatbot) dahil uçtan uca fullstack çözümler sunuyorum. Müşterileriniz 7/24 randevu alabilir, siz de tüm süreci admin panelinden yönetebilirsiniz.","llms_summary":"GZL Teknoloji tarafından randevu sistemli kurumsal web siteleri geliştiririm hizmeti; kapsam, teslim planı ve teknik gereksinimler projeye göre netleştirilerek sunulur.","tags":["Yazılım & Teknoloji","Web Yazılım"]}', 'randevu sistemli kurumsal web siteleri geliştiririm', 'randevu sistemli kurumsal web siteleri geliştiririm | GZL Teknoloji', 'Klinik, spa, güzellik merkezi ve sağlık profesyonelleri için modern kurumsal web siteleri geliştiriyorum. Online randevu alma modülü, takvim entegrasyonu, çok dilli destek ve yapay zeka destekli sohbet botu (AI chatbot) dahil uçtan uca fullstack çözümler sunuyorum. Müşterileriniz 7/24 randevu alabilir, siz de tüm süreci admin panelinden yönetebilirsiniz.', 'Yazılım & Teknoloji,Web Yazılım,GZL Teknoloji', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
('10000002-0000-4000-8000-0016840182', '10000000-0000-4000-8000-0016840182', 'en', 'appointment-corporate-website', 'Corporate Website with Online Appointment Booking', 'We develop modern corporate websites for clinics, spas, beauty centers and healthcare professionals. Our end-to-end full-stack solutions include an online appointment booking module, calendar integration, multilingual support and an AI-powered chatbot. Your customers can book appointments 24/7, while you manage the entire process from the admin panel.', '{"source":"bionluk","source_id":840182,"category":"Yazılım & Teknoloji > Web Yazılım","packages":[{"title":"Starter Package","price":5000,"currency":"TRY","duration_days":7,"revisions":2,"description":"Single-language corporate website. Service pages and contact form included.","options":[{"title":"Sayfa Sayısı","value":7,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":false,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":"Professional Package","price":10000,"currency":"TRY","duration_days":15,"revisions":5,"description":"Multilingual corporate website + online appointment booking system and calendar management included.","options":[{"title":"Sayfa Sayısı","value":10,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]},{"title":"Enterprise Package","price":20000,"currency":"TRY","duration_days":30,"revisions":7,"description":"Multilingual corporate website + online appointment system + AI-powered chatbot. Admin panel included.","options":[{"title":"Sayfa Sayısı","value":15,"unit":null},{"title":"Tasarım Özelleştirme","value":true,"unit":null},{"title":"İçerik Girişi","value":true,"unit":null},{"title":"Responsive Tasarım","value":true,"unit":null},{"title":"Kaynak Kodları","value":true,"unit":null}]}],"html":"We develop modern corporate websites for clinics, spas, beauty centers and healthcare professionals. Our end-to-end full-stack solutions include an online appointment booking module, calendar integration, multilingual support and an AI-powered chatbot. Your customers can book appointments 24/7, while you manage the entire process from the admin panel.","llms_summary":"Corporate Website with Online Appointment Booking is delivered by GZL Technology with project-specific scope, technical requirements and a clear delivery plan.","tags":["Yazılım & Teknoloji","Web Yazılım"]}', 'Corporate Website with Online Appointment Booking', 'Corporate Website with Online Appointment Booking | GZL Technology', 'We develop modern corporate websites for clinics, spas, beauty centers and healthcare professionals. Our end-to-end full-stack solutions include an online appointment booking module, calendar integration, multilingual support and an AI-powered chatbot. Your customers can book appointments 24/7, while you manage the entire process from the admin panel.', 'GZL Technology,software,service', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000')
